let S, route = location.hash.slice(1)||'dashboard', collapsed=localStorage.getItem('cadence-collapsed')==='1', taskFilter={q:'',status:'',priority:'',attention:'',sort:'deadline',direction:1}, columns=new Set(['status','priority','assignee','deadline','complexity']), page=1, detail=null, activeShift=null, period='This Month', employeeId=null, reportType='Employee Monthly Report', range={start:'',end:''}, reportFilters={employee:'',team:'',status:'',complexity:'',quality:'',q:''}, previousFocus=null;
