async function api(path,method='GET',data){
  const writing=method!=='GET';
  if(writing){pendingWrites++;syncFailure=false;updateSync();}
  try{
    const r=await fetch('/api/'+path,{method,headers:writing?{'Content-Type':'application/json','X-Cadence-Request':'1'}:{},body:data===undefined?undefined:JSON.stringify(data)});
    const value=await r.json();
    if(!r.ok){if(r.status===401&&path!=='login')login();throw new Error(value.error||'The request could not be completed. Please retry.');}
    if(writing)lastSync=new Date();return value;
  }catch(error){if(writing)syncFailure=true;throw error;}
  finally{if(writing){pendingWrites--;updateSync();}}
}
function syncLabel(){return pendingWrites?'Saving changes…':syncFailure?'Update failed · check the last error':lastSync?'Updated '+lastSync.toLocaleTimeString('en',{hour:'2-digit',minute:'2-digit'}):'Workspace loaded';}
function updateSync(){const el=$('#sync-state');if(el){el.textContent=syncLabel();el.className=syncFailure?'danger':'';}}
function toast(message,error=false){const t=$('#toast');t.innerHTML=`${icon(error?'alert':'check')}<span>${esc(message)}</span>`;t.className=`visible ${error?'error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',4500);}
async function refresh(renderPage=true){S=await api('state');lastSync=new Date();if(!range.start)setRange();if(renderPage)render();else updateSync();}
function navigate(to){
  if(route.startsWith('tasks'))taskViews.set(route,{filter:{...taskFilter},page,scroll:window.scrollY||0});
  route=to;location.hash=to;closeOverlay(true);
  const saved=taskViews.get(to);
  if(to.startsWith('tasks')){taskFilter=saved?{...saved.filter}:defaultTaskFilter();page=saved?.page||1;}
  render();requestAnimationFrame(()=>{window.scrollTo?.(0,saved?.scroll||0);$('#main')?.focus({preventScroll:true});});
}
function setRange(){const d=new Date((S?.today||new Date().toISOString().slice(0,10))+'T12:00:00');let start=new Date(d.getFullYear(),d.getMonth(),1,12),end=d;if(period==='Last Month'){start=new Date(d.getFullYear(),d.getMonth()-1,1,12);end=new Date(d.getFullYear(),d.getMonth(),0,12);}if(period==='Quarter')start=new Date(d.getFullYear(),Math.floor(d.getMonth()/3)*3,1,12);const iso=x=>`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`;range={start:iso(start),end:iso(end)};}
