function login(){S=null;taskViews.clear();taskDrafts.clear();taskFilter=defaultTaskFilter();page=1;activeShift=null;employeeId=null;detail=null;returnTask=null;document.body.classList.remove('modal-open');$('#app').inert=false;$('#overlay').innerHTML='';$('#app').innerHTML=`<main class="login"><section class="login-story"><a class="brand"><span class="brand-mark">${icon('chart')}</span>cadence<span class="brand-dot">.</span></a><div><span class="eyebrow">YOUR TEAM. IN SYNC.</span><h1>Good work deserves<br>a clearer view.</h1><p>A considered workspace for the people behind<br>security operations.</p><div class="login-principles"><div>${icon('tasks')}<span><strong>Work with context</strong><small>Tasks, reviews and decisions in one place.</small></span></div><div>${icon('shift')}<span><strong>Leave a clear record</strong><small>Daily activities, issues and traceable tickets.</small></span></div><div>${icon('chart')}<span><strong>See the contribution</strong><small>Performance grounded in recorded work.</small></span></div></div></div><small>WORK MANAGEMENT · SHIFT ACTIVITY · PERFORMANCE</small></section><section class="login-form"><div class="login-box"><span class="eyebrow">WELCOME BACK</span><h2>Sign in to your workspace</h2><p class="muted">Pick up where your team left off.</p><form id="login-form">${field('Work email',input('email','','email','required autocomplete="username" placeholder="you@company.com"'))}${field('Password',input('password','','password','required autocomplete="current-password" placeholder="Enter your password"'))}<div class="form-error" role="alert"></div><button class="button primary wide" type="submit">Sign in ${icon('arrow')}</button></form><details class="demo-help"><summary>Using the local demo?</summary><p>Email: <strong>sara@cadence.local</strong><br>Password: <strong>Cadence-demo-2026!</strong></p><p>Available only when the server is started in demo mode.</p></details><p class="small muted">An internal workspace for focused teams.</p></div></section></main>`;}
const navs=[['dashboard','grid','Dashboard'],['tasks','tasks','Tasks'],['shifts','shift','Shift logs'],['team','team','Team'],['performance','chart','Performance'],['reports','report','Reports']];
function notificationItems(){const tasks=S.tasks.filter(t=>(t.assignee===S.me.id||t.status==='Review')&&(overdue(t)||['Review','Returned'].includes(t.status)));const mentions=S.comments.filter(c=>c.body.toLowerCase().includes('@'+S.me.name.split(' ')[0].toLowerCase()));return {tasks,mentions,count:tasks.length+mentions.length};}
